<?php

namespace MongoDB\Driver;

use MongoDB\BSON\Int64;
use MongoDB\Driver\Exception\InvalidArgumentException;

/**
 * <div id="class.mongodb-driver-cursor" class="reference"> <h1 class="title">The MongoDB\Driver\Cursor class</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.0.0)</p>  <div class="section" id="mongodb-driver-cursor.intro">   <h2 class="title">简介</h2>   <p class="simpara">    The <span class="classname"><strong class="classname">MongoDB\Driver\Cursor</strong></span> class encapsulates    the results of a MongoDB command or query and may be returned by    <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::executeCommand()}</span> or    <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::executeQuery()}</span>, respectively.   </p>  </div>  <div class="section" id="mongodb-driver-cursor.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="modifier">final</span>     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\Driver\Cursor</strong>     </span>     <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.mongodb-driver-cursorinterface.php" class="interfacename">MongoDB\Driver\CursorInterface</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">private</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-cursor.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>()</div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-cursor.current.php" class="methodname" style="color:#CC7832">current</a></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">null</a></span></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-cursor.getid.php" class="methodname" style="color:#CC7832">getId</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-int64.php" class="type MongoDB\BSON\Int64" style="color:#EAB766">MongoDB\BSON\Int64</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-cursor.getserver.php" class="methodname" style="color:#CC7832">getServer</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="type MongoDB\Driver\Server" style="color:#EAB766">MongoDB\Driver\Server</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-cursor.isdead.php" class="methodname" style="color:#CC7832">isDead</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-cursor.key.php" class="methodname" style="color:#CC7832">key</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-cursor.next.php" class="methodname" style="color:#CC7832">next</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-cursor.rewind.php" class="methodname" style="color:#CC7832">rewind</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-cursor.settypemap.php" class="methodname" style="color:#CC7832">setTypeMap</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$typemap</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-cursor.toarray.php" class="methodname" style="color:#CC7832">toArray</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-cursor.valid.php" class="methodname" style="color:#CC7832">valid</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>   }</div>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>PECL mongodb 1.9.0</td>       <td>        Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.iterator.php" class="interfacename">Iterator</a></span>.       </td>      </tr>      <tr>       <td>PECL mongodb 1.6.0</td>       <td>        Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-driver-cursorinterface.php" class="interfacename">MongoDB\Driver\CursorInterface</a></span>,        which extends <span class="interfacename"><a href="https://php.net/manual/zh/class.traversable.php" class="interfacename">Traversable</a></span>.       </td>      </tr>     </tbody>       </table>  </div>  <div class="section" id="mongodb-driver-cursor.examples">   <h2 class="title">示例</h2>   <div class="example" id="mongodb-driver-cursor.examples.foreach">    <p><strong>示例 #1 Reading a result set</strong></p>    <div class="example-contents"><p>     <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::executeCommand()}</span> and     <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::executeQuery()}</span> both return     their result(s) as a <span class="classname"><strong class="classname">MongoDB\Driver\Cursor</strong></span> object.     This object can be used to iterate over the result set of the command or     query.    </p></div>    <div class="example-contents"><p>     Because <span class="classname"><strong class="classname">MongoDB\Driver\Cursor</strong></span> implements the     <span class="interfacename"><a href="https://php.net/manual/zh/class.traversable.php" class="interfacename">Traversable</a></span> interface, you can simply     iterate over the result set with     <a href="https://php.net/manual/zh/control-structures.foreach.php" class="link"><span class="literal">foreach</span></a>.    </p></div>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// Insert some documents so that our query returns information <br></span><span style="color: #9876AA">\$bulkWrite </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$bulkWrite</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'name' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'Ceres'</span><span style="color: #007700">, </span><span style="color: #DD0000">'size' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">946</span><span style="color: #007700">, </span><span style="color: #DD0000">'distance' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2.766</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulkWrite</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'name' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'Vesta'</span><span style="color: #007700">, </span><span style="color: #DD0000">'size' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">525</span><span style="color: #007700">, </span><span style="color: #DD0000">'distance' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2.362</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeBulkWrite</span><span style="color: #007700">(</span><span style="color: #DD0000">"test.asteroids"</span><span style="color: #007700">, </span><span style="color: #9876AA">\$bulkWrite</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// Query for all the items in the collection <br></span><span style="color: #9876AA">\$query </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Query</span><span style="color: #007700">( [] );<br><br></span><span style="color: #FF8000">// Query the "asteroids" collection of the "test" database <br></span><span style="color: #9876AA">\$cursor </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeQuery</span><span style="color: #007700">(</span><span style="color: #DD0000">"test.asteroids"</span><span style="color: #007700">, </span><span style="color: #9876AA">\$query</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// \$cursor now contains an object that wraps around the result set. Use<br> * foreach() to iterate over all the result <br></span><span style="color: #007700">foreach(</span><span style="color: #9876AA">\$cursor </span><span style="color: #007700">as </span><span style="color: #9876AA">\$document</span><span style="color: #007700">) {<br>    </span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$document</span><span style="color: #007700">);<br>}<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="cdata"><blockquote style="border:1px gray solid;"><br>stdClass&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[_id]&nbsp;=&gt;&nbsp;MongoDB\BSON\ObjectId&nbsp;Object<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[oid]&nbsp;=&gt;&nbsp;5a4cff2f122d3321565d8cc2<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br><br>&nbsp;&nbsp;&nbsp;&nbsp;[name]&nbsp;=&gt;&nbsp;Ceres<br>&nbsp;&nbsp;&nbsp;&nbsp;[size]&nbsp;=&gt;&nbsp;946<br>&nbsp;&nbsp;&nbsp;&nbsp;[distance]&nbsp;=&gt;&nbsp;2.766<br>)<br>stdClass&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[_id]&nbsp;=&gt;&nbsp;MongoDB\BSON\ObjectId&nbsp;Object<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[oid]&nbsp;=&gt;&nbsp;5a4cff2f122d3321565d8cc3<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br><br>&nbsp;&nbsp;&nbsp;&nbsp;[name]&nbsp;=&gt;&nbsp;Vesta<br>&nbsp;&nbsp;&nbsp;&nbsp;[size]&nbsp;=&gt;&nbsp;525<br>&nbsp;&nbsp;&nbsp;&nbsp;[distance]&nbsp;=&gt;&nbsp;2.362<br>)<br></blockquote></div>    </div>   </div>   <div class="example" id="mongodb-driver-cursor.examples.tailable">    <p><strong>示例 #2 Reading a result set for a tailable cursor</strong></p>    <div class="example-contents"><p>     <a href="https://www.mongodb.com/docs/manual/core/tailable-cursors" class="link external">»&nbsp;Tailable cursors</a>     are a special type of MongoDB cursor that allows the client to read some     results and then wait until more documents become available. These cursors     are primarily used with     <a href="https://www.mongodb.com/docs/manual/core/capped-collections" class="link external">»&nbsp;Capped Collections</a>     and <a href="https://www.mongodb.com/docs/manual/changeStreams" class="link external">»&nbsp;Change Streams</a>.    </p></div>    <div class="example-contents"><p>     While normal cursors can be iterated once with <span class="literal">foreach</span>,     that approach will not work with tailable cursors. When     <span class="literal">foreach</span> is used with a tailable cursor, the loop will     stop upon reaching the end of the initial result set. Attempting to     continue iteration on the cursor with a second     <span class="literal">foreach</span> would throw an exception, since PHP attempts to     rewind the cursor. Similar to result objects in other database drivers,     cursors in MongoDB only support forward iteration, which means they cannot     be rewound.    </p></div>    <div class="example-contents"><p>     In order to continuously read from a tailable cursor, the Cursor object     must be wrapped with an <span class="classname"><a href="https://php.net/manual/zh/class.iteratoriterator.php" class="classname">IteratorIterator</a></span>. This     allows the application to directly control the cursor's iteration, avoid     inadvertently rewinding the cursor, and decide when to wait for new results     or stop iteration entirely.    </p></div>    <div class="example-contents"><p>     In order to demonstrate a tailable cursor in action, two scripts will be     used: a "producer" and a "consumer". The producer script will create a new     capped collection using the     <a href="https://www.mongodb.com/docs/manual/reference/command/create" class="link external">»&nbsp;create</a> command     and proceed to insert a new document into that collection each second.    </p></div>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeCommand</span><span style="color: #007700">(</span><span style="color: #DD0000">'test'</span><span style="color: #007700">, new </span><span style="color: #9876AA">MongoDB\Driver\Command</span><span style="color: #007700">([<br>    </span><span style="color: #DD0000">'create' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'asteroids'</span><span style="color: #007700">,<br>    </span><span style="color: #DD0000">'capped' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">true</span><span style="color: #007700">,<br>    </span><span style="color: #DD0000">'size' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1048576</span><span style="color: #007700">,<br>]));<br><br>while (</span><span style="color: #9876AA">true</span><span style="color: #007700">) {<br>    </span><span style="color: #9876AA">\$bulkWrite </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">;<br>    </span><span style="color: #9876AA">\$bulkWrite</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'createdAt' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\UTCDateTime</span><span style="color: #007700">]);<br>    </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeBulkWrite</span><span style="color: #007700">(</span><span style="color: #DD0000">'test.asteroids'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$bulkWrite</span><span style="color: #007700">);<br><br>    </span><span style="color: #9876AA">sleep</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">);<br>}<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>    <div class="example-contents"><p>     With the producer script still running, a second consumer script may be     executed to read the inserted documents using a tailable cursor, indicated     by the <span class="literal">tailable</span> and <span class="literal">awaitData</span> options     to <span class="function">{@link MongoDB\Driver\Query::__construct()}</span>.    </p></div>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$query </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Query</span><span style="color: #007700">([], [<br>    </span><span style="color: #DD0000">'tailable' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">true</span><span style="color: #007700">,<br>    </span><span style="color: #DD0000">'awaitData' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">true</span><span style="color: #007700">,<br>]);<br><br></span><span style="color: #9876AA">\$cursor </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeQuery</span><span style="color: #007700">(</span><span style="color: #DD0000">'test.asteroids'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$query</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$iterator </span><span style="color: #007700">= new </span><span style="color: #9876AA">IteratorIterator</span><span style="color: #007700">(</span><span style="color: #9876AA">\$cursor</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$iterator</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">rewind</span><span style="color: #007700">();<br><br>while (</span><span style="color: #9876AA">true</span><span style="color: #007700">) {<br>    if (</span><span style="color: #9876AA">\$iterator</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">valid</span><span style="color: #007700">()) {<br>        </span><span style="color: #9876AA">\$document </span><span style="color: #007700">= </span><span style="color: #9876AA">\$iterator</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">current</span><span style="color: #007700">();<br>        </span><span style="color: #9876AA">printf</span><span style="color: #007700">(</span><span style="color: #DD0000">"Consumed document created at: %s\n"</span><span style="color: #007700">, </span><span style="color: #9876AA">\$document</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createdAt</span><span style="color: #007700">);<br>    }<br><br>    </span><span style="color: #9876AA">\$iterator</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">next</span><span style="color: #007700">();<br>}<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>    <div class="example-contents"><p>     The consumer script will start by quickly printing all available documents     in the capped collection (as if <span class="literal">foreach</span> had been used);     however, it will not terminate upon reaching the end of the initial result     set. Since the cursor is tailable, calling     <span class="function">{@link IteratorIterator::next()}</span> will block and wait for     additional results. <span class="function">{@link IteratorIterator::valid()}</span> is also     used to check if there is actually data available to read at each step.    </p></div>    <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:      <span class="simpara">      This example uses the <span class="literal">awaitData</span> query option to      instruct the server to block for a short period (e.g. one second) at the      end of the result set before returning a response to the driver. This is      used to prevent the driver from aggressively polling the server when there      are no results available. The <span class="literal">maxAwaitTimeMS</span> option may      be used in conjunction with <span class="literal">tailable</span> and      <span class="literal">awaitData</span> to specify the amount of time that the server      should block when it reaches the end of the result set.     </span>    </p></blockquote>   </div>  </div>  <div class="section">   <h2 class="title">错误／异常</h2>   <p class="simpara">    When iterating over the cursor object, BSON data is converted into PHP    variables. This iteration can cause the following Exceptions:   </p>   <ul class="simplelist">    <li>     Throws     <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> if     a class in the type map cannot be instantiated or does not implement     <span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-bson-unserializable.php" class="interfacename">MongoDB\BSON\Unserializable</a></span>.    </li>    <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-unexpectedvalueexception.php" class="classname">MongoDB\Driver\Exception\UnexpectedValueException</a></span> if the input did not contain exactly one BSON document. Possible reasons include, but are not limited to, invalid BSON, extra data (after reading one BSON document), or an unexpected <a href="https://github.com/mongodb/mongo-c-driver/tree/master/src/libbson" class="link external">»&nbsp;libbson</a> error.</li>   </ul>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\Driver\Cursor::__construct} — Create a new Cursor (not used)</li><li>{@link MongoDB\Driver\Cursor::current} — Returns the current element</li><li>{@link MongoDB\Driver\Cursor::getId} — Returns the ID for this cursor</li><li>{@link MongoDB\Driver\Cursor::getServer} — Returns the server associated with this cursor</li><li>{@link MongoDB\Driver\Cursor::isDead} — Checks if the cursor is exhausted or may have additional results</li><li>{@link MongoDB\Driver\Cursor::key} — Returns the current result's index within the cursor</li><li>{@link MongoDB\Driver\Cursor::next} — Advances the cursor to the next result</li><li>{@link MongoDB\Driver\Cursor::rewind} — Rewind the cursor to the first result</li><li>{@link MongoDB\Driver\Cursor::setTypeMap} — Sets a type map to use for BSON unserialization</li><li>{@link MongoDB\Driver\Cursor::toArray} — Returns an array containing all results for this cursor</li><li>{@link MongoDB\Driver\Cursor::valid} — Checks if the current position in the cursor is valid</li></ul></div>
 * 
 * The MongoDB\Driver\Cursor class encapsulates the results of a MongoDB command or query and may be returned by MongoDB\Driver\Manager::executeCommand() or MongoDB\Driver\Manager::executeQuery(), respectively.
 * @link https://php.net/manual/zh/class.mongodb-driver-cursor.php
 */
final class Cursor implements CursorInterface
{
    /**
 * <div id="mongodb-driver-cursor.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Cursor::__construct</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Cursor::__construct</span> — <span class="dc-title">Create a new Cursor (not used)</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-cursor.construct-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">private</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Cursor::__construct</strong></span>()</div>  <p class="simpara">   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-cursor.php" class="classname">MongoDB\Driver\Cursor</a></span> objects are returned as the   result of an executed command or query and cannot be constructed directly.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-cursor.construct-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-cursor.construct-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\Driver\Manager::executeCommand()} - Execute a database command</span></li>   <li><span class="function">{@link MongoDB\Driver\Manager::executeQuery()} - Execute a database query</span></li>   <li><span class="function">{@link MongoDB\Driver\Server::executeCommand()} - Execute a database command on this server</span></li>   <li><span class="function">{@link MongoDB\Driver\Server::executeQuery()} - Execute a database query on this server</span></li>  </ul> </div></div>
 * 
     * Create a new Cursor
     * MongoDB\Driver\Cursor objects are returned as the result of an executed command or query and cannot be constructed directly.
     * @link https://php.net/manual/zh/mongodb-driver-cursor.construct.php
     */
    final private function __construct() {}


    final public function __wakeup() {}

    /**
 * <div id="mongodb-driver-cursor.current" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Cursor::current</h1>  <p class="verinfo">(mongodb &gt;=1.9.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Cursor::current</span> — <span class="dc-title">Returns the current element</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-cursor.current-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Cursor::current</strong></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">null</a></span></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-cursor.current-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-cursor.current-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the current result document as an array or object, depending on the   cursor's type map. If iteration has not started or the current position   is not valid, <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> will be returned.  </p> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-cursor.current-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Iterator::current()} - 返回当前元素</span></li>  </ul> </div></div>
 * 
     * Returns the current element.
     * @link https://www.php.net/manual/en/mongodb-driver-cursor.current.php
     */
    public function current(): array|object|null {}

    /**
 * <div id="mongodb-driver-cursor.getid" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Cursor::getId</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Cursor::getId</span> — <span class="dc-title">Returns the ID for this cursor</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-cursor.getid-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Cursor::getId</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-int64.php" class="type MongoDB\BSON\Int64" style="color:#EAB766">MongoDB\BSON\Int64</a></span></div>  <p class="simpara">   Returns the ID for this cursor, which uniquely identifies the cursor on the   server.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-cursor.getid-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-cursor.getid-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the ID for this cursor. The ID will be returned as a   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-int64.php" class="classname">MongoDB\BSON\Int64</a></span> object.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-cursor.getid-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-cursor.getid-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 2.0.0</td>      <td>       The return type was changed to <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-int64.php" class="classname">MongoDB\BSON\Int64</a></span>.       The <span class="parameter" style="color:#3A95FF">asInt64</span> parameter was removed.      </td>     </tr>     <tr>      <td>PECL mongodb 1.20.0</td>      <td>       Deprecated returning a <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-cursorid.php" class="classname">MongoDB\Driver\CursorId</a></span>.       Added the <span class="parameter" style="color:#3A95FF">asInt64</span> argument to ease migration for       future versions. If <span class="parameter" style="color:#3A95FF">asInt64</span> is <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>, the ID       will be returned as a <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-int64.php" class="classname">MongoDB\BSON\Int64</a></span>.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-cursor.getid-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\Cursor::getId()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br></span><span style="color: #FF8000">// In this example, we insert several documents into the collection and specify<br> * a smaller batchSize to ensure that the first batch contains only a subset of<br> * our results and the cursor remains open on the server. <br></span><span style="color: #9876AA">\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">"mongodb://localhost:27017"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$query </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Query</span><span style="color: #007700">([], [</span><span style="color: #DD0000">'batchSize' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeBulkWrite</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$cursor </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeQuery</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$query</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$cursor</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getId</span><span style="color: #007700">(</span><span style="color: #9876AA">true</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(MongoDB\BSON\Int64)#5&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;["integer"]=&gt;<br>&nbsp;&nbsp;string(11)&nbsp;"94810124093"<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-cursor.getid-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-int64.php" class="classname">MongoDB\BSON\Int64</a></span></li>  </ul> </div></div>
 * 
     * Returns the cursor ID associated with this cursor. A cursor ID cursor uniquely identifies the cursor on the server.
     *
     * @link https://php.net/manual/zh/mongodb-driver-cursor.getid.php
     * @throws InvalidArgumentException on argument parsing errors.
     */
    final public function getId(): Int64 {}

    /**
 * <div id="mongodb-driver-cursor.getserver" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Cursor::getServer</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Cursor::getServer</span> — <span class="dc-title">Returns the server associated with this cursor</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-cursor.getserver-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Cursor::getServer</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="type MongoDB\Driver\Server" style="color:#EAB766">MongoDB\Driver\Server</a></span></div>  <p class="simpara">   Returns the <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="classname">MongoDB\Driver\Server</a></span> associated with this   cursor. This is the server that executed the   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-query.php" class="classname">MongoDB\Driver\Query</a></span> or   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-command.php" class="classname">MongoDB\Driver\Command</a></span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-cursor.getserver-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-cursor.getserver-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="classname">MongoDB\Driver\Server</a></span> associated with this   cursor.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-cursor.getserver-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-cursor.getserver-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\Cursor::getServer()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">"mongodb://localhost:27017"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$query </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Query</span><span style="color: #007700">([]);<br><br></span><span style="color: #9876AA">\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeBulkWrite</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$cursor </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeQuery</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$query</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$cursor</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getServer</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(MongoDB\Driver\Server)#5&nbsp;(10)&nbsp;{<br>&nbsp;&nbsp;["host"]=&gt;<br>&nbsp;&nbsp;string(9)&nbsp;"localhost"<br>&nbsp;&nbsp;["port"]=&gt;<br>&nbsp;&nbsp;int(27017)<br>&nbsp;&nbsp;["type"]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;["is_primary"]=&gt;<br>&nbsp;&nbsp;bool(false)<br>&nbsp;&nbsp;["is_secondary"]=&gt;<br>&nbsp;&nbsp;bool(false)<br>&nbsp;&nbsp;["is_arbiter"]=&gt;<br>&nbsp;&nbsp;bool(false)<br>&nbsp;&nbsp;["is_hidden"]=&gt;<br>&nbsp;&nbsp;bool(false)<br>&nbsp;&nbsp;["is_passive"]=&gt;<br>&nbsp;&nbsp;bool(false)<br>&nbsp;&nbsp;["last_hello_response"]=&gt;<br>&nbsp;&nbsp;array(8)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["isWritablePrimary"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;bool(true)<br>&nbsp;&nbsp;&nbsp;&nbsp;["maxBsonObjectSize"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(16777216)<br>&nbsp;&nbsp;&nbsp;&nbsp;["maxMessageSizeBytes"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(48000000)<br>&nbsp;&nbsp;&nbsp;&nbsp;["maxWriteBatchSize"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(1000)<br>&nbsp;&nbsp;&nbsp;&nbsp;["localTime"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;object(MongoDB\BSON\UTCDateTime)#6&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;["milliseconds"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;int(1446505367907)<br>&nbsp;&nbsp;&nbsp;&nbsp;}<br>&nbsp;&nbsp;&nbsp;&nbsp;["maxWireVersion"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(3)<br>&nbsp;&nbsp;&nbsp;&nbsp;["minWireVersion"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(0)<br>&nbsp;&nbsp;&nbsp;&nbsp;["ok"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;float(1)<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;["round_trip_time"]=&gt;<br>&nbsp;&nbsp;int(584)<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-cursor.getserver-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="classname">MongoDB\Driver\Server</a></span></li>  </ul> </div></div>
 * 
     * Returns the MongoDB\Driver\Server associated with this cursor. This is the server that executed the query or command.
     * @link https://php.net/manual/zh/mongodb-driver-cursor.getserver.php
     * @throws InvalidArgumentException on argument parsing errors.
     */
    final public function getServer(): Server {}

    /**
 * <div id="mongodb-driver-cursor.isdead" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Cursor::isDead</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Cursor::isDead</span> — <span class="dc-title">Checks if the cursor is exhausted or may have additional results</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-cursor.isdead-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Cursor::isDead</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="simpara">   Checks whether there are definitely no additional results available on the   cursor. This method is similar to the   <a href="https://www.mongodb.com/docs/manual/reference/method/cursor.isExhausted/" class="link external">»&nbsp;cursor.isExhausted()</a>   method in the MongoDB shell and is primarily useful when iterating   <a href="https://www.mongodb.com/docs/manual/core/tailable-cursors/" class="link external">»&nbsp;tailable cursors</a>.  </p>  <p class="para">   A cursor has no additional results and is considered "dead" when one of the   following is true:   </p><ul class="simplelist">    <li>     The current batch has been fully iterated <em>and</em> the     cursor ID is zero (i.e. a     <a href="https://www.mongodb.com/docs/manual/reference/command/getMore/" class="link external">»&nbsp;getMore</a>     cannot be issued).    </li>    <li>An error was encountered while iterating the cursor.</li>    <li>The cursor reached its configured limit.</li>   </ul>    <p class="para">   By design, it is not possible to always determine whether a cursor has   additional results. The cases where a cursor <em>may</em> have   more data available is as follows:   </p><ul class="simplelist">    <li>     There are additional documents in the current batch, which are buffered on     the client side. Iterating will fetch a document from the local buffer.    </li>    <li>     There are no additional documents in the current batch (i.e. local buffer),     but the cursor ID is non-zero. Iterating will request more documents from     the server via a     <a href="https://www.mongodb.com/docs/manual/reference/command/getMore/" class="link external">»&nbsp;getMore</a>     operation, which may or may not return additional results and/or indicate     that the cursor has been closed on the server by returning zero for its ID.    </li>   </ul>   </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-cursor.isdead-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-cursor.isdead-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if there are definitely no additional results available on the   cursor, and <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-cursor.isdead-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-cursor.isdead-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\Cursor::isDead()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">"mongodb://localhost:27017"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$query </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Query</span><span style="color: #007700">([]);<br><br></span><span style="color: #9876AA">\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeBulkWrite</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$cursor </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeQuery</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$query</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$iterator </span><span style="color: #007700">= new </span><span style="color: #9876AA">IteratorIterator</span><span style="color: #007700">(</span><span style="color: #9876AA">\$cursor</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$iterator</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">rewind</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$cursor</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">isDead</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$iterator</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">next</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$cursor</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">isDead</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$iterator</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">next</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$cursor</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">isDead</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$iterator</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">next</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$cursor</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">isDead</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">bool(false)<br>bool(false)<br>bool(false)<br>bool(true)</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-cursor.isdead-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://www.mongodb.com/docs/manual/core/tailable-cursors/" class="link external">»&nbsp;Tailable Cursors</a> in the MongoDB manual</li>   <li><a href="https://www.mongodb.com/docs/manual/reference/method/cursor.isExhausted/" class="link external">»&nbsp;cursor.isExhausted()</a> in the MongoDB manual</li>  </ul> </div></div>
 * 
     * Checks if a cursor is still alive
     * @link https://php.net/manual/zh/mongodb-driver-cursor.isdead.php
     * @return bool
     * @throws InvalidArgumentException On argument parsing errors
     */
    final public function isDead(): bool {}

    /**
 * <div id="mongodb-driver-cursor.key" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Cursor::key</h1>  <p class="verinfo">(mongodb &gt;=1.9.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Cursor::key</span> — <span class="dc-title">Returns the current result's index within the cursor</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-cursor.key-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Cursor::key</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-cursor.key-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-cursor.key-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   The current result's numeric index within the cursor.  </p> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-cursor.key-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Iterator::key()} - 返回当前元素的键</span></li>  </ul> </div></div>
 * 
     * Returns the current result's index within the cursor.
     * @link https://www.php.net/manual/en/mongodb-driver-cursor.key.php
     */
    public function key(): ?int {}

    /**
 * <div id="mongodb-driver-cursor.next" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Cursor::next</h1>  <p class="verinfo">(mongodb &gt;=1.9.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Cursor::next</span> — <span class="dc-title">Advances the cursor to the next result</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-cursor.next-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Cursor::next</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-cursor.next-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-cursor.next-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Moves the current position to the next element in the cursor.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-cursor.next-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-connectionexception.php" class="classname">MongoDB\Driver\Exception\ConnectionException</a></span> if connection to the server fails (for reasons other than authentication).</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-authenticationexception.php" class="classname">MongoDB\Driver\Exception\AuthenticationException</a></span> if authentication is needed and fails.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-cursor.next-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Iterator::next()} - 向前移动到下一个元素</span></li>  </ul> </div></div>
 * 
     * Advances the cursor to the next result.
