    /**
 * <div id="mongodb-driver-cursor.rewind" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Cursor::rewind</h1>  <p class="verinfo">(mongodb &gt;=1.9.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Cursor::rewind</span> — <span class="dc-title">Rewind the cursor to the first result</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-cursor.rewind-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Cursor::rewind</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   If the cursor has advanced beyond its first position, it can no longer be   rewound.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-cursor.rewind-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-cursor.rewind-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-cursor.rewind-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-connectionexception.php" class="classname">MongoDB\Driver\Exception\ConnectionException</a></span> if connection to the server fails (for reasons other than authentication).</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-authenticationexception.php" class="classname">MongoDB\Driver\Exception\AuthenticationException</a></span> if authentication is needed and fails.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-logicexception.php" class="classname">MongoDB\Driver\Exception\LogicException</a></span> if this method is called after the cursor has advanced beyond its first position.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-cursor.rewind-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Iterator::rewind()} - 返回到迭代器的第一个元素</span></li>  </ul> </div></div>
 * 
     * Rewind the cursor to the first result.
     * @link https://www.php.net/manual/en/mongodb-driver-cursor.rewind.php
     * @throws \MongoDB\Driver\Exception\InvalidArgumentException on argument parsing errors.
     * @throws \MongoDB\Driver\Exception\ConnectionException if connection to the server fails (for reasons other than authentication).
     * @throws \MongoDB\Driver\Exception\AuthenticationException if authentication is needed and fails.
     * @throws \MongoDB\Driver\Exception\LogicException if this method is called after the cursor has advanced beyond its first position.
     */
    public function rewind(): void {}

    /**
 * <div id="mongodb-driver-cursor.settypemap" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Cursor::setTypeMap</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Cursor::setTypeMap</span> — <span class="dc-title">Sets a type map to use for BSON unserialization</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-cursor.settypemap-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Cursor::setTypeMap</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$typemap</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Sets the <a href="https://php.net/manual/zh/mongodb.persistence.php#mongodb.persistence.typemaps" class="link">type map   configuration</a> to use when unserializing the BSON results into PHP   values.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-cursor.settypemap-parameters">  <h3 class="title">参数</h3>  <dl>          <dt><span class="parameter" style="color:#3A95FF">typeMap</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>)</dt>    <dd>     <span class="simpara">      <a href="https://php.net/manual/zh/mongodb.persistence.php#mongodb.persistence.typemaps" class="link">Type map configuration</a>.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-cursor.settypemap-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-cursor.settypemap-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul>  <p class="para">   When iterating over the cursor, the following exceptions can also be thrown   due to an incorrect type map configuration:   </p><ul class="simplelist">    <li>     Throws     <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> if     a class in the type map cannot be instantiated or does not implement     <span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-bson-unserializable.php" class="interfacename">MongoDB\BSON\Unserializable</a></span>.    </li>   </ul>   </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-cursor.settypemap-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\Cursor::setTypeMap()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">"mongodb://localhost:27017"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$id </span><span style="color: #007700">= </span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeBulkWrite</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$query </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Query</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">\$id</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$cursor </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeQuery</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$query</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$cursor</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">setTypeMap</span><span style="color: #007700">([</span><span style="color: #DD0000">'root' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'array'</span><span style="color: #007700">]);<br><br>foreach (</span><span style="color: #9876AA">\$cursor </span><span style="color: #007700">as </span><span style="color: #9876AA">\$document</span><span style="color: #007700">) {<br>    </span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$document</span><span style="color: #007700">);<br>}<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(2)&nbsp;{<br>&nbsp;&nbsp;["_id"]=&gt;<br>&nbsp;&nbsp;object(MongoDB\BSON\ObjectId)#6&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["oid"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(24)&nbsp;"56424fb76118fd3267180741"<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;["x"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-cursor.settypemap-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://php.net/manual/zh/mongodb.persistence.php" class="xref">Persisting Data</a></li>  </ul> </div></div>
 * 
     * Sets a type map to use for BSON unserialization
     *
     * @link https://php.net/manual/zh/mongodb-driver-cursor.settypemap.php
     *
     * @throws InvalidArgumentException On argument parsing errors or if a class in the type map cannot
     * be instantiated or does not implement MongoDB\BSON\Unserializable
     */
    final public function setTypeMap(array $typemap): void {}

    /**
 * <div id="mongodb-driver-cursor.toarray" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Cursor::toArray</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Cursor::toArray</span> — <span class="dc-title">Returns an array containing all results for this cursor</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-cursor.toarray-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Cursor::toArray</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="simpara">   Iterates the cursor and returns its results in an array.   <span class="function">{@link MongoDB\Driver\Cursor::setTypeMap()}</span> may be used to control   how documents are unserialized into PHP values.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-cursor.toarray-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-cursor.toarray-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> containing all results for this cursor.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-cursor.toarray-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-cursor.toarray-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\Cursor::toArray()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">"mongodb://localhost:27017"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeBulkWrite</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$query </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Query</span><span style="color: #007700">([]);<br></span><span style="color: #9876AA">\$cursor </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeQuery</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$query</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$cursor</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toArray</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;object(stdClass)#6&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["_id"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;object(MongoDB\BSON\ObjectId)#5&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;["oid"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;string(24)&nbsp;"564259a96118fd40b41bcf61"<br>&nbsp;&nbsp;&nbsp;&nbsp;}<br>&nbsp;&nbsp;&nbsp;&nbsp;["x"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;object(stdClass)#8&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["_id"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;object(MongoDB\BSON\ObjectId)#7&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;["oid"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;string(24)&nbsp;"564259a96118fd40b41bcf62"<br>&nbsp;&nbsp;&nbsp;&nbsp;}<br>&nbsp;&nbsp;&nbsp;&nbsp;["x"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;object(stdClass)#10&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["_id"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;object(MongoDB\BSON\ObjectId)#9&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;["oid"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;string(24)&nbsp;"564259a96118fd40b41bcf63"<br>&nbsp;&nbsp;&nbsp;&nbsp;}<br>&nbsp;&nbsp;&nbsp;&nbsp;["x"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(3)<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-cursor.toarray-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\Driver\Cursor::setTypeMap()} - Sets a type map to use for BSON unserialization</span></li>  </ul> </div></div>
 * 
     * Returns an array of all result documents for this cursor
     * @link https://php.net/manual/zh/mongodb-driver-cursor.toarray.php
     * @throws InvalidArgumentException On argument parsing errors
     */
    final public function toArray(): array {}

    /**
 * <div id="mongodb-driver-cursor.valid" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Cursor::valid</h1>  <p class="verinfo">(mongodb &gt;=1.9.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Cursor::valid</span> — <span class="dc-title">Checks if the current position in the cursor is valid</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-cursor.valid-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Cursor::valid</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-cursor.valid-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-cursor.valid-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if the current cursor position is valid, <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.  </p> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-cursor.valid-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link Iterator::valid()} - 检查当前位置是否有效</span></li>  </ul> </div></div>
 * 
     * Checks if the current position in the cursor is valid.
     * @link https://www.php.net/manual/en/mongodb-driver-cursor.valid.php
     */
    public function valid(): bool {}
